import { NotFoundError } from "../domain/domain-error";
import { Task } from "../domain/task";
import { TaskRepository } from "../domain/task-repository";
import { UserRepository } from "../domain/user-repository";
import { AssignTaskDto } from "./dtos";

export class AssignTaskUseCase {
  constructor(
    private readonly tasks: TaskRepository,
    private readonly users: UserRepository,
  ) {}

  async execute(dto: AssignTaskDto): Promise<Task> {
    const task = await this.tasks.findById(dto.taskId);
    if (!task) throw new NotFoundError("task not found");
    if (typeof dto.assigneeId !== "string" || !(await this.users.findById(dto.assigneeId))) {
      throw new NotFoundError("assignee not found");
    }
    task.assignTo(dto.assigneeId);
    await this.tasks.save(task);
    return task;
  }
}

